def algorithm(func, dim, lb, ub, budget, rng):
    x_best = -np.ones(dim)
    for _ in range(budget):
        x_curr = x_best.copy()
        for i in range(dim):
            noise = rng.uniform(-1, 1)
            x_curr[i] += noise * (ub - lb) / 2
            if x_curr[i] < lb:
                x_curr[i] = lb
            elif x_curr[i] > ub:
                x_curr[i] = ub
        f_curr = func(x_curr)
        if f_curr < func(x_best):
            x_best = x_curr.copy()
    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    bounds = np.array([ub - lb] * dim)
    center = (lb + ub) / 2 * np.ones(dim)

    for _ in range(budget):
        step_size = min(1, max(bounds) / 10)
        new_center = center + (np.random.uniform(-0.5, 0.5, size=dim) * step_size)

        clipped_new_center = np.clip(new_center, lb, ub)

        if func(clipped_new_center) < func(center):
            center = clipped_new_center

    return center
